  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, status, attribution_type, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Masalahnya: Proyek Butuh Notifikasi Saat Tidak Ada WiFi$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Banyak proyek Arduino perlu memberi kabar ke pemiliknya dari jauh: alarm kebocoran gas di rumah, sensor pintu gudang, atau pengingat tangki air penuh. Masalahnya, tidak semua lokasi punya WiFi. Di sinilah jaringan seluler menjadi solusi: sebuah modul GSM kecil bernama SIM800L bisa mengirim SMS ke HP Anda dari mana saja selama ada sinyal seluler. Artikel ini memandu Anda merakit dan mengirim SMS pertama dari Arduino.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Kenapa Modul GSM SIM800L Cocok untuk Ini$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$SIM800L adalah modul GSM/GPRS yang murah dan hemat daya saat siaga. Ia berkomunikasi dengan Arduino lewat jalur serial UART (pin TX/RX) menggunakan perintah AT, yaitu perintah teks sederhana seperti AT+CMGS untuk mengirim SMS. Kelebihan utamanya: tidak butuh internet, cukup kartu SIM dengan pulsa atau paket SMS aktif. Catatan penting: modul ini butuh catu daya 3,4 sampai 4,4 volt dengan arus puncak sekitar 2 ampere saat mengirim, jadi jangan disuplai langsung dari pin 5V Arduino.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Alat dan Bahan yang Diperlukan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$li$Board Arduino Uno atau Nano$li$, $li$Modul GSM SIM800L (versi dengan antena)$li$, $li$Kartu SIM aktif yang sudah diisi pulsa atau paket SMS$li$, $li$Adaptor 5V minimal 2A atau modul step-down ke 4V$li$, $li$Kabel jumper secukupnya$li$, $li$Breadboard (opsional)$li$, $li$Resistor 10k dan 20k untuk pembagi tegangan (opsional tapi dianjurkan)$li$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Langkah-Langkah Merakit dan Mengirim SMS$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$li$Pasang kartu SIM ke slot SIM800L, pastikan PIN kartu sudah dinonaktifkan lewat HP.$li$, $li$Sambungkan VCC modul ke catu 4V, GND ke GND Arduino.$li$, $li$Sambungkan TX modul ke pin 10 Arduino dan RX modul ke pin 11 Arduino (pakai SoftwareSerial), atau silang langsung bila memakai port serial perangkat keras.$li$, $li$Turunkan tegangan jalur TX Arduino (5V) ke sekitar 2,8V dengan pembagi tegangan sebelum masuk ke RX modul.$li$, $li$Buka Serial Monitor, kirim perintah AT dan pastikan modul menjawab OK.$li$, $li$Kirim AT+CMGF=1 untuk mode teks, lalu AT+CMGS="08xxxxxxxxxx" diikuti isi pesan dan diakhiri karakter Ctrl+Z.$li$, $li$Tunggu balasan +CMGS: nomor referensi yang artinya SMS terkirim.$li$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Risiko yang Perlu Diwaspadai$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$li$Catu daya lemah membuat modul restart berulang (boot loop) dan SMS gagal terkirim.$li$, $li$Tegangan logika 5V langsung ke RX modul bisa merusak SIM800L dalam jangka panjang.$li$, $li$Kartu SIM yang masih terkunci PIN membuat modul tidak bisa mendaftar ke jaringan.$li$, $li$Setiap SMS memotong pulsa; uji secukupnya agar pulsa tidak habis.$li$, $li$Jangan memakai perangkat ini untuk mengirim spam atau pesan mengganggu karena melanggar aturan operator.$li$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Penyelesaian dan Tindak Lanjut$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $txt$Setelah SMS pertama berhasil diterima di HP, proyek Anda sudah punya jalur notifikasi jarak jauh. Periksa hasilnya: apakah pesan tiba dalam hitungan detik dan isinya utuh. Tindak lanjutnya, gabungkan modul ini dengan sensor sesuai kebutuhan, misalnya sensor gas MQ-2 untuk alarm kebocoran atau sensor PIR untuk peringatan gerakan. Matikan modul atau cabut dayanya saat tidak dipakai agar hemat listrik dan pulsa.$txt$));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, status, attribution_type, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Masalahnya: Rawon Kurang Hitam dan Kurang Gurih$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Rawon yang enak punya dua ciri: kuahnya hitam pekat dan rasanya gurih dalam dengan aroma rempah yang kuat. Masalah yang sering terjadi di dapur rumahan adalah kuah yang warnanya cokelat pucat dan rasanya hambar seperti sop biasa. Penyebab utamanya hampir selalu ada pada kluwek, bahan pemberi warna hitam khas rawon, entah takarannya kurang atau kualitasnya tidak bagus.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Kenapa Kluwek Jadi Kunci Rawon$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Kluwek adalah biji buah kepayang yang difermentasi. Daging buahnya yang berwarna hitam kecokelatan inilah yang memberi warna pekat sekaligus rasa gurih yang dalam pada kuah rawon. Pilih kluwek yang berat dan berisi, dengan daging buah berwarna hitam kecokelatan dan tidak berbau tengik. Hindari kluwek yang dagingnya keputihan atau terasa sangat pahit saat dicicipi sedikit, karena akan merusak seluruh masakan.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Bahan-Bahan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$li$Daging sapi sandung lamur 500 gram, potong dadu$li$, $li$Kluwek 5 sampai 6 buah, ambil daging buahnya$li$, $li$Bawang merah 8 siung dan bawang putih 5 siung$li$, $li$Kemiri sangrai 4 butir$li$, $li$Ketumbar 1 sendok teh, kunyit 2 cm, jahe 2 cm$li$, $li$Lengkuas 3 cm (geprek), serai 2 batang (geprek)$li$, $li$Daun jeruk 4 lembar, daun salam 2 lembar$li$, $li$Garam, gula, dan kaldu sapi secukupnya$li$, $li$Pelengkap: tauge pendek, telur asin, sambal, kerupuk udang, bawang goreng$li$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Langkah Memasak Rawon$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$li$Rebus daging sapi hingga empuk dan kaldunya keluar, saring lalu sisihkan.$li$, $li$Haluskan bawang merah, bawang putih, kemiri, ketumbar, kunyit, jahe, dan daging kluwek sampai benar-benar halus.$li$, $li$Tumis bumbu halus bersama lengkuas, serai, daun jeruk, dan daun salam hingga harum dan matang.$li$, $li$Masukkan tumisan bumbu ke dalam kaldu, aduk hingga kuah berubah hitam pekat.$li$, $li$Masukkan kembali daging, bumbui garam, gula, dan kaldu sapi, lalu masak dengan api kecil 20 menit agar bumbu meresap.$li$, $li$Koreksi rasa: gurih, sedikit manis, dan aroma kluwek terasa jelas.$li$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Risiko: Kluwek Pahit dan Daging Alot$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$li$Kluwek berkualitas buruk membuat kuah pahit dan tidak bisa diperbaiki; selalu cicipi sedikit daging kluwek sebelum dipakai.$li$, $li$Daging yang direbus terlalu singkat akan alot; gunakan api kecil dan waktu cukup atau panci presto.$li$, $li$Bumbu yang kurang matang saat ditumis menimbulkan aroma langu pada kuah.$li$, $li$Terlalu banyak kluwek membuat kuah getir; tambahkan bertahap mulai dari 5 buah.$li$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Penyelesaian: Sajikan dan Simpan dengan Benar$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $txt$Sajikan rawon panas-panas dengan nasi putih, tauge pendek mentah, irisan telur asin, sambal, kerupuk udang, dan taburan bawang goreng. Hasil yang benar: kuah hitam pekat, daging empuk, dan rasa gurih yang dalam. Sisa rawon bisa disimpan di kulkas hingga 3 hari; hangatkan dengan api kecil dan tambahkan sedikit air bila kuah menyusut.$txt$));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, status, attribution_type, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Apa Itu Timah?$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Timah adalah unsur kimia dengan simbol Sn (dari bahasa Latin stannum) dan nomor atom 50. Ia termasuk logam pasca-transisi yang lunak, berwarna keperakan, dan sudah dikenal manusia sejak ribuan tahun lalu sebagai bahan pembuat perunggu, yaitu paduan tembaga dan timah. Hingga kini timah tetap menjadi logam penting, terutama di dunia elektronik.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Sifat-Sifat Khas Timah$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Timah murni sangat lunak sehingga mudah dibentuk, dan titik leburnya relatif rendah, sekitar 232 derajat Celsius. Ia tahan terhadap korosi udara sehingga sering dipakai sebagai pelapis logam lain. Sifat uniknya adalah suara berderak khas saat batangan timah dibengkokkan, yang oleh para ilmuwan disebut tangisan timah akibat pergeseran kristal di dalamnya.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Timah dan Solder Elektronik$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Kegunaan timah yang paling dekat dengan kehidupan modern adalah sebagai bahan utama solder, yaitu logam penyambung komponen pada papan sirkuit. Solder tradisional adalah paduan timah dan timbal dengan titik lebur eutektik sekitar 183 derajat Celsius, sehingga mudah meleleh dengan solder biasa. Kini banyak dipakai solder bebas timbal berbahan timah-perak-tembaga demi alasan kesehatan, meski titik leburnya sedikit lebih tinggi.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Timah dalam Kehidupan Sehari-Hari$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Selain solder, timah melapisi kaleng makanan (disebut tinplate) agar tidak berkarat, menjadi bahan paduan perunggu untuk patung dan lonceng, serta dipakai dalam industri kaca dan keramik. Indonesia adalah salah satu produsen timah terbesar di dunia, dengan tambang utama di Kepulauan Bangka Belitung yang sudah beroperasi sejak masa kolonial.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Keamanan, Kesehatan, dan Lingkungan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Timah murni relatif tidak beracun, tetapi timbal yang dulu dicampur dalam solder bersifat racun bagi saraf sehingga teknisi dianjurkan memakai solder bebas timbal dan bekerja di ruangan berventilasi baik. Penambangan timah yang tidak bertanggung jawab dapat merusak hutan dan laut, sehingga penting memilih produk dari sumber yang memperhatikan lingkungan serta mendaur ulang limbah elektronik yang mengandung timah.$txt$));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, status, attribution_type, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Apa Itu Agresi Militer Belanda II?$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Agresi Militer Belanda II adalah operasi militer besar yang dilancarkan Belanda pada 19 Desember 1948 dengan menyerang Yogyakarta, yang saat itu menjadi ibu kota Republik Indonesia. Belanda menyebutnya aksi polisionil, sedangkan Indonesia memandangnya sebagai agresi militer karena melanggar Perjanjian Renville yang masih berlaku.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Latar Belakang Serangan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Setelah Agresi Militer I tahun 1947, perundingan Renville menghasilkan gencatan senjata tetapi tidak menyelesaikan status kedaulatan Indonesia. Belanda menilai Republik melemah, terutama setelah pecahnya pemberontakan di Madiun pada September 1948, dan memutuskan menyelesaikan masalah dengan kekuatan militer untuk mengembalikan kekuasaannya atas Indonesia.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Jalannya Serangan 19 Desember 1948$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Serangan diawali pendaratan pasukan payung di lapangan terbang Maguwo pada pagi hari, disusul serangan darat ke pusat kota Yogyakarta. Dalam waktu singkat pasukan Belanda menguasai ibu kota dan menangkap para pemimpin Republik, termasuk Soekarno, Hatta, dan Syahrir, yang kemudian diasingkan ke luar Jawa. Namun sebelum tertangkap, para pemimpin sempat mengirim mandat agar pemerintahan dilanjutkan dari daerah.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Pemerintahan Darurat dan Perang Gerilya$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Sesuai mandat, dibentuk Pemerintah Darurat Republik Indonesia (PDRI) di Bukittinggi di bawah Syafruddin Prawiranegara agar negara tetap berjalan. Sementara itu Panglima Besar Soedirman yang sedang sakit memimpin perang gerilya dari hutan, menerapkan strategi bumi hangus dan serangan berpindah-pindah agar Belanda tidak bisa menguasai wilayah secara penuh.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Tekanan Internasional dan Penyelesaian$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Agresi ini memicu kecaman dunia: Dewan Keamanan PBB mengeluarkan resolusi yang menuntut penghentian agresi dan pembebasan para pemimpin Indonesia, Amerika Serikat mengancam menghentikan bantuan Marshall Plan ke Belanda. Puncaknya, Serangan Umum 1 Maret 1949 yang merebut kembali Yogyakarta selama enam jam membuktikan Republik masih ada. Rangkaian perundingan Roem-Royen dan Konferensi Meja Bundar akhirnya berujung pada pengakuan kedaulatan Indonesia pada 27 Desember 1949.$txt$));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, status, attribution_type, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Tujuan Pembelajaran$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Setelah mempelajari materi ini, kamu diharapkan mampu menjelaskan pengertian stratifikasi sosial, mengidentifikasi sifat-sifatnya (tertutup, terbuka, campuran), menyebutkan dasar-dasar pembentukannya menurut Max Weber, serta memberi contoh stratifikasi sosial yang ada di masyarakat Indonesia.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Pengertian dan Sifat Stratifikasi Sosial$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Stratifikasi sosial adalah pelapisan masyarakat ke dalam kelas-kelas sosial secara bertingkat, dari atas ke bawah. Istilah ini dipopulerkan oleh Pitirim A. Sorokin yang melihat bahwa setiap masyarakat memiliki lapisan dengan hak dan kewajiban yang berbeda. Sifatnya ada tiga: tertutup, seperti sistem kasta di India di mana status tidak bisa berubah; terbuka, seperti sistem kelas di masyarakat modern di mana orang bisa naik turun lewat pendidikan dan kerja keras; dan campuran, yang menggabungkan keduanya.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Dasar Pembentukan: Kekayaan, Kekuasaan, Kehormatan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Max Weber menjelaskan bahwa stratifikasi terbentuk dari tiga dimensi: kelas (class) yang didasarkan pada kepemilikan ekonomi atau kekayaan, status (status) yang didasarkan pada kehormatan dan gaya hidup, serta partai atau kekuasaan (power) yang didasarkan pada kemampuan memengaruhi orang lain. Ketiganya bisa berjalan sendiri-sendiri: orang kaya belum tentu dihormati, dan orang berkuasa belum tentu kaya.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Contoh Stratifikasi Sosial di Indonesia$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Di Indonesia yang menganut sistem terbuka, contoh stratifikasi terlihat pada perbedaan tingkat pendidikan, jenis pekerjaan, dan tingkat penghasilan, misalnya antara pekerja formal dan informal. Mobilitas sosial vertikal sangat mungkin terjadi: anak petani bisa menjadi dokter lewat pendidikan. Meski begitu, unsur tertutup masih tersisa dalam adat tertentu, misalnya gelar kebangsawanan yang diwariskan dalam sebagian masyarakat adat.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Latihan Soal$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$li$1. Jelaskan pengertian stratifikasi sosial menurut Pitirim A. Sorokin!$li$, $li$2. Sebutkan dan jelaskan tiga sifat stratifikasi sosial beserta contohnya!$li$, $li$3. Uraikan tiga dimensi stratifikasi menurut Max Weber!$li$, $li$4. Mengapa Indonesia digolongkan memiliki stratifikasi terbuka? Jelaskan!$li$, $li$5. Berikan dua contoh mobilitas sosial vertikal ke atas yang pernah kamu amati!$li$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Kunci Jawaban$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$li$1. Pelapisan masyarakat ke dalam kelas-kelas sosial secara bertingkat berdasarkan perbedaan hak, kewajiban, dan prestise.$li$, $li$2. Tertutup (kasta, status tidak bisa berubah), terbuka (kelas, bisa berubah lewat usaha), campuran (gabungan keduanya).$li$, $li$3. Kelas/kekayaan (ekonomi), status/kehormatan (gaya hidup), kekuasaan (kemampuan memengaruhi).$li$, $li$4. Karena status sosial bisa berubah melalui pendidikan, pekerjaan, dan prestasi; tidak ditentukan kelahiran semata.$li$, $li$5. Contoh: anak buruh menjadi PNS lewat kuliah; pedagang kecil menjadi pengusaha besar. (jawaban bisa bervariasi)$li$])));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, status, attribution_type, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Tujuan Pembelajaran$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Setelah belajar materi ini, kamu diharapkan bisa menjelaskan apa itu lingkungan, menyebutkan contoh lingkungan alam dan lingkungan buatan di sekitarmu, serta menyebutkan cara-cara sederhana menjaga kebersihan lingkungan.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Apa Itu Lingkungan?$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Lingkungan adalah segala sesuatu yang ada di sekitar kita. Ada lingkungan alam, yaitu ciptaan Tuhan seperti udara, air, tumbuhan, dan hewan. Ada juga lingkungan buatan, yaitu hasil karya manusia seperti rumah, sekolah, dan jalan. Kita hidup dan beraktivitas di dalam lingkungan setiap hari.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Contoh Lingkungan Alam$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Lingkungan alam contohnya adalah sawah tempat padi tumbuh, sungai tempat air mengalir, gunung yang tinggi, pantai dengan pasirnya, serta kebun dan hutan tempat banyak tumbuhan dan hewan hidup. Lingkungan alam memberi kita udara segar, air bersih, dan makanan.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Contoh Lingkungan Buatan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Lingkungan buatan contohnya adalah rumah tempat kita tinggal, sekolah tempat kita belajar, jalan raya untuk kendaraan, jembatan penyeberangan sungai, dan pasar tempat orang berbelanja. Semua itu dibuat manusia untuk memudahkan kehidupan.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Cara Menjaga Lingkungan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Lingkungan yang bersih membuat kita sehat. Cara menjaganya mudah: buang sampah pada tempatnya, tidak mencoret-coret dinding, menanam tumbuhan di halaman, menghemat air saat mandi dan mencuci, serta ikut kerja bakti membersihkan lingkungan bersama tetangga.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Latihan Soal dan Kunci Jawaban$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$li$1. Apa yang dimaksud dengan lingkungan? (Segala sesuatu yang ada di sekitar kita)$li$, $li$2. Sebutkan dua contoh lingkungan alam! (Sawah, sungai, gunung, pantai)$li$, $li$3. Sebutkan dua contoh lingkungan buatan! (Rumah, sekolah, jalan, jembatan)$li$, $li$4. Mengapa kita harus menjaga kebersihan lingkungan? (Agar sehat dan nyaman)$li$, $li$5. Sebutkan dua cara menjaga lingkungan! (Buang sampah pada tempatnya, menanam tumbuhan, hemat air)$li$])));
